summary_al <- al %>%
  group_by(day, noadults) %>%
  summarize(
    mean_F = ifelse(all(is.na(F)), NA, mean(F, na.rm = TRUE)),  # Mean of F
    sd_F = ifelse(all(is.na(F)), NA, sd(F, na.rm = TRUE))       # Standard deviation of F
